def _configure_minimax_draft_argmax(self) -> None:
    """Enable the private experiment only for its validated model contract."""
    if os.environ.get("MM3_FUSED_DRAFT_ARGMAX_EXPERIMENT") != "1":
        return
    from vllm.platforms import current_platform

    config = self.vllm_config
    head = getattr(self.model, "lm_head", None)
    processor = getattr(self.model, "logits_processor", None)
    if (
        not current_platform.is_rocm()
        or config.model_config.hf_config.model_type != "minimax_m3_vl"
        or config.parallel_config.tensor_parallel_size != 4
        or config.parallel_config.pipeline_parallel_size != 1
        or config.lora_config is not None
        or self.speculative_config.method != "eagle3"
        or self.speculative_config.draft_sample_method != "greedy"
        or head is None
        or processor is None
        or head.tp_size != 4
        or head.embedding_dim != 6144
        or head.weight.dtype != torch.bfloat16
        or processor.org_vocab_size != 200064
        or processor.scale != 1.0
        or processor.soft_cap is not None
    ):
        raise ValueError(
            "Fused draft argmax requires MiniMax-M3 TP4 BF16 greedy Eagle3"
        )
    mapping = getattr(self.model, "draft_id_to_target_id", None)
    if mapping is not None and (
        mapping.numel() != processor.org_vocab_size
        or torch.count_nonzero(mapping).item() != 0
    ):
        raise ValueError("Fused draft argmax requires identity draft-to-target IDs")
    self._use_minimax_fused_draft_argmax = True
    logger.info(
        "MiniMax-M3 fused draft argmax enabled: original BF16 LM head, "
        "compact rank-major partials, no full-vocabulary gather or scatter"
    )

def _greedy_sample_draft(self, hidden_states: torch.Tensor) -> torch.Tensor:
    if self._use_minimax_fused_draft_argmax:
        from vllm.models.minimax_m3.amd.ops.draft_argmax import (
            identity_vocab_top_tokens,
        )

        return identity_vocab_top_tokens(self.model, hidden_states)
    if self.use_local_argmax_reduction:
        return self.model.get_top_tokens(hidden_states)
    logits = self.model.compute_logits(hidden_states)
    return logits.argmax(dim=-1)

